// Client-side post search for /blog.
//
// The blog page already lists every post, so search filters and reorders
// those cards in place rather than rendering its own results. The index
// (/search.json, generated by scripts/build.py) is fetched on first use.
// Every whitespace-separated term must match somewhere in a post; title and
// tag hits rank above body-text hits. ?q= pre-fills the box (tag links on
// post pages use it) and is kept in sync so a search can be shared.
(function () {
  "use strict";

  var form = document.querySelector("form.search");
  var input = document.getElementById("search-input");
  var status = document.querySelector(".search-status");
  var list = document.querySelector(".post-list");
  if (!form || !input || !list) return;

  var cards = Array.prototype.slice.call(list.children);
  var byUrl = {};
  cards.forEach(function (card) { byUrl[card.dataset.url] = card; });

  var index = null;
  var loading = null;

  function fold(s) {
    return s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  }

  function load() {
    if (!loading) {
      loading = fetch("/search.json")
        .then(function (r) {
          if (!r.ok) throw new Error("search.json: HTTP " + r.status);
          return r.json();
        })
        .then(function (posts) {
          index = posts.map(function (p) {
            return {
              url: p.url,
              title: fold(p.title),
              tags: fold(p.tags.join(" ")),
              body: fold(p.description + " " + p.text),
            };
          });
        })
        .catch(function (err) {
          loading = null; // allow a retry on the next keystroke
          status.textContent = "Search is unavailable right now.";
          throw err;
        });
    }
    return loading;
  }

  function score(entry, terms) {
    var total = 0;
    for (var i = 0; i < terms.length; i++) {
      var t = terms[i];
      var s = 0;
      if (entry.title.indexOf(t) !== -1) s += 10;
      if (entry.tags.indexOf(t) !== -1) s += 5;
      if (entry.body.indexOf(t) !== -1) s += 1;
      if (s === 0) return 0;
      total += s;
    }
    return total;
  }

  function show(query) {
    var terms = fold(query).split(/\s+/).filter(Boolean);
    if (!terms.length) {
      cards.forEach(function (card) { card.hidden = false; list.appendChild(card); });
      status.textContent = "";
      return;
    }
    var hits = index
      .map(function (entry, order) { return { entry: entry, order: order, score: score(entry, terms) }; })
      .filter(function (h) { return h.score > 0 && byUrl[h.entry.url]; })
      .sort(function (a, b) { return b.score - a.score || a.order - b.order; });

    cards.forEach(function (card) { card.hidden = true; });
    hits.forEach(function (h) {
      var card = byUrl[h.entry.url];
      card.hidden = false;
      list.appendChild(card);
    });
    status.textContent = hits.length
      ? hits.length + (hits.length === 1 ? " post" : " posts") + " matching “" + query.trim() + "”"
      : "No posts match “" + query.trim() + "”";
  }

  function syncUrl(query) {
    var url = new URL(window.location.href);
    if (query.trim()) url.searchParams.set("q", query.trim());
    else url.searchParams.delete("q");
    history.replaceState(null, "", url);
  }

  function run() {
    var query = input.value;
    syncUrl(query);
    load().then(function () {
      if (input.value === query) show(query);
    }, function () {}); // failure already reported in the status line
  }

  form.hidden = false;
  form.addEventListener("submit", function (e) { e.preventDefault(); run(); });
  input.addEventListener("input", run);
  input.addEventListener("focus", function () { load().catch(function () {}); }, { once: true });

  var initial = new URLSearchParams(window.location.search).get("q");
  if (initial) {
    input.value = initial;
    run();
  }
})();
